1	package copilotcli
2	
3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"encoding/json"
8		"fmt"
9		"io"
10		"os"
11	
12		"github.com/entireio/cli/cmd/entire/cli/agent"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14	)
15	
16	// Compile-time interface checks.
17	var (
18		_ agent.TranscriptAnalyzer = (*CopilotCLIAgent)(nil)
19		_ agent.TokenCalculator    = (*CopilotCLIAgent)(nil)
20	)
21	
22	// copilotEvent is a single line in events.jsonl.
23	type copilotEvent struct {
24		Type      string          `json:"type"`
25		Data      json.RawMessage `json:"data"`
26		ID        string          `json:"id"`
27		Timestamp string          `json:"timestamp"`
28		ParentID  string          `json:"parentId"`
29	}
30	
31	const (
32		eventTypeUserMessage  = "user.message"
33		eventTypeAssistantMsg = "assistant.message"
34		eventTypeToolExecDone = "tool.execution_complete"
35		eventTypeModelChange  = "session.model_change"
36	)
37	
38	// userMessageData is the data payload for user.message events.
39	// IMPORTANT: The field is "content", not "message" — verified from real Copilot JSONL.
40	type userMessageData struct {
41		Content string `json:"content"`
42	}
43	
44	type assistantMessageData struct {
45		Content string `json:"content"`
46	}
47	
48	// modelChangeData is the data payload for session.model_change events.
49	// Copilot CLI emits this early in the transcript with the LLM model being used.
50	type modelChangeData struct {
51		NewModel string `json:"newModel"`
52	}
53	
54	type toolExecCompleteData struct {
55		ToolCallID    string        `json:"toolCallId"`
56		Model         string        `json:"model"`
57		ToolTelemetry toolTelemetry `json:"toolTelemetry"`
58	}
59	
60	type toolTelemetry struct {
61		Metrics    toolMetrics    `json:"metrics"`
62		Properties toolProperties `json:"properties"`
63	}
64	
65	type toolMetrics struct {
66		LinesAdded   int `json:"linesAdded"`
67		LinesRemoved int `json:"linesRemoved"`
68	}
69	
70	// toolProperties contains string-encoded metadata from tool execution.
71	// filePaths is a JSON-encoded string array, e.g. "[\"path/to/file.txt\"]".
72	type toolProperties struct {
73		FilePaths string `json:"filePaths"`
74	}
75	
76	// parseEventsFromBytes scans JSONL data and returns all parsed events.
77	// Malformed lines are silently skipped.
78	func parseEventsFromBytes(data []byte) ([]copilotEvent, error) {
79		return parseEventsFromOffset(data, 0)
80	}
81	
82	// parseEventsFromOffset scans JSONL data and returns events starting after
83	// the first startOffset lines. Malformed lines are silently skipped.
84	func parseEventsFromOffset(data []byte, startOffset int) ([]copilotEvent, error) {
85		var events []copilotEvent
86		scanner := bufio.NewScanner(bytes.NewReader(data))
87		scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 10*1024*1024) // 10 MB max line
88		lineNum := 0
89	
90		for scanner.Scan() {
91			lineNum++
92			if lineNum <= startOffset {
93				continue
94			}
95	
96			line := scanner.Bytes()
97			if len(line) == 0 {
98				continue
99			}
100	
101			var ev copilotEvent
102			if err := json.Unmarshal(line, &ev); err != nil {
103				continue // skip malformed lines
104			}
105			events = append(events, ev)
106		}
107	
108		if err := scanner.Err(); err != nil {
109			return events, fmt.Errorf("transcript scanner error: %w", err)
110		}
111	
112		return events, nil
113	}
114	
115	// extractModifiedFilesFromEvents collects file paths from tool.execution_complete
116	// events and returns a deduplicated list.
117	func extractModifiedFilesFromEvents(events []copilotEvent) []string {
118		seen := make(map[string]bool)
119		var files []string
120	
121		for i := range events {
122			if events[i].Type != eventTypeToolExecDone {
123				continue
124			}
125	
126			var data toolExecCompleteData
127			if err := json.Unmarshal(events[i].Data, &data); err != nil {
128				continue
129			}
130	
131			// filePaths is a JSON-encoded string array in properties, e.g. "[\"path/to/file\"]"
132			if data.ToolTelemetry.Properties.FilePaths == "" {
133				continue
134			}
135			var paths []string
136			if err := json.Unmarshal([]byte(data.ToolTelemetry.Properties.FilePaths), &paths); err != nil {
137				continue
138			}
139			for _, fp := range paths {
140				if fp != "" && !seen[fp] {
141					seen[fp] = true
142					files = append(files, fp)
143				}
144			}
145		}
146	
147		return files
148	}
149	
150	// extractPromptsFromEvents collects content from user.message events.
151	func extractPromptsFromEvents(events []copilotEvent) []string {
152		var prompts []string
153	
154		for i := range events {
155			if events[i].Type != eventTypeUserMessage {
156				continue
157			}
158	
159			var data userMessageData
160			if err := json.Unmarshal(events[i].Data, &data); err != nil {
161				continue
162			}
163	
164			if data.Content != "" {
165				prompts = append(prompts, data.Content)
166			}
167		}
168	
169		return prompts
170	}
171	
172	// extractSummaryFromEvents returns the content of the last assistant.message event.
173	func extractSummaryFromEvents(events []copilotEvent) string {
174		for i := len(events) - 1; i >= 0; i-- {
175			if events[i].Type != eventTypeAssistantMsg {
176				continue
177			}
178	
179			var data assistantMessageData
180			if err := json.Unmarshal(events[i].Data, &data); err != nil {
181				continue
182			}
183	
184			if data.Content != "" {
185				return data.Content
186			}
187		}
188	
189		return ""
190	}
191	
192	// extractModelFromEvents returns the model from transcript events.
193	// First checks session.model_change events, then falls back to the model field
194	// in tool.execution_complete events (Copilot CLI includes model per tool call).
195	func extractModelFromEvents(events []copilotEvent) string {
196		// Primary: session.model_change (explicit model declaration)
197		for i := len(events) - 1; i >= 0; i-- {
198			if events[i].Type != eventTypeModelChange {
199				continue
200			}
201	
202			var data modelChangeData
203			if err := json.Unmarshal(events[i].Data, &data); err != nil {
204				continue
205			}
206	
207			if data.NewModel != "" {
208				return data.NewModel
209			}
210		}
211	
212		// Fallback: tool.execution_complete events include a model field
213		for i := len(events) - 1; i >= 0; i-- {
214			if events[i].Type != eventTypeToolExecDone {
215				continue
216			}
217	
218			var data toolExecCompleteData
219			if err := json.Unmarshal(events[i].Data, &data); err != nil {
220				continue
221			}
222	
223			if data.Model != "" {
224				return data.Model
225			}
226		}
227	
228		return ""
229	}
230	
231	// sessionShutdownData is the data payload for session.shutdown events.
232	// Contains aggregate model metrics for the entire session.
233	// modelMetrics is a JSON object keyed by model name (e.g. "claude-sonnet-4.6"),
234	// not an array — using map[string] here matches the real Copilot CLI wire format.
235	type sessionShutdownData struct {
236		ModelMetrics map[string]modelMetric `json:"modelMetrics"`
237	}
238	
239	// modelMetric contains per-model token usage aggregates.
240	// The model name is the map key in sessionShutdownData.ModelMetrics, not a field.
241	type modelMetric struct {
242		Requests modelRequests `json:"requests"`
243		Usage    modelUsage    `json:"usage"`
244	}
245	
246	type modelRequests struct {
247		Count int `json:"count"`
248	}
249	
250	type modelUsage struct {
251		InputTokens      int `json:"inputTokens"`
252		OutputTokens     int `json:"outputTokens"`
253		CacheReadTokens  int `json:"cacheReadTokens"`
254		CacheWriteTokens int `json:"cacheWriteTokens"`
255	}
256	
257	// assistantMessageTokenData is used as a fallback when session.shutdown is not
258	// yet available. Each assistant.message may carry an outputTokens field.
259	type assistantMessageTokenData struct {
260		OutputTokens int `json:"outputTokens"`
261	}
262	
263	const eventTypeSessionShutdown = "session.shutdown"
264	
265	// CalculateTokenUsage computes token usage from the Copilot CLI JSONL transcript.
266	// For full transcripts (fromOffset == 0), it prefers session.shutdown, which
267	// contains session-wide aggregates. For sliced transcripts, session.shutdown
268	// would overcount because it is not checkpoint-scoped, so we fall back to
269	// summing assistant.message outputTokens within the slice.
270	func (c *CopilotCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
271		events, err := parseEventsFromOffset(transcriptData, fromOffset)
272		if err != nil {
273			return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
274		}
275	
276		return extractTokenUsageFromEvents(events, fromOffset == 0), nil
277	}
278	
279	// extractTokenUsageFromEvents extracts token usage from parsed events.
280	// Prefers session.shutdown aggregate only when the caller is looking at the
281	// full transcript; otherwise falls back to per-message outputTokens.
282	func extractTokenUsageFromEvents(events []copilotEvent, preferSessionShutdown bool) *agent.TokenUsage {
283		if preferSessionShutdown {
284			// session.shutdown is authoritative, but only for full-session totals.
285			for i := len(events) - 1; i >= 0; i-- {
286				if events[i].Type != eventTypeSessionShutdown {
287					continue
288				}
289	
290				var data sessionShutdownData
291				if err := json.Unmarshal(events[i].Data, &data); err != nil {
292					logging.Debug(context.Background(), "copilot-cli: session.shutdown data unmarshal failed",
293						"err", err)
294					continue
295				}
296	
297				if len(data.ModelMetrics) == 0 {
298					continue
299				}
300	
301				// Sum across all models.
302				usage := &agent.TokenUsage{}
303				for _, m := range data.ModelMetrics {
304					usage.InputTokens += m.Usage.InputTokens
305					usage.OutputTokens += m.Usage.OutputTokens
306					usage.CacheReadTokens += m.Usage.CacheReadTokens
307					usage.CacheCreationTokens += m.Usage.CacheWriteTokens
308					usage.APICallCount += m.Requests.Count
309				}
310				return usage
311			}
312		}
313	
314		// Fallback: sum outputTokens from assistant.message events
315		usage := &agent.TokenUsage{}
316		for i := range events {
317			if events[i].Type != eventTypeAssistantMsg {
318				continue
319			}
320	
321			var data assistantMessageTokenData
322			if err := json.Unmarshal(events[i].Data, &data); err != nil {
323				continue
324			}
325			usage.OutputTokens += data.OutputTokens
326			if data.OutputTokens > 0 {
327				usage.APICallCount++
328			}
329		}
330	
331		return usage
332	}
333	
334	// ExtractModelFromTranscript extracts the LLM model name from a Copilot CLI
335	// transcript. It prefers session.model_change events (explicit model
336	// declarations), but falls back to the model field on tool.execution_complete
337	// events for Copilot CLI versions that do not emit session.model_change.
338	// Returns the last observed model, or empty string if unavailable.
339	func ExtractModelFromTranscript(ctx context.Context, transcriptPath string) string {
340		if transcriptPath == "" {
341			return ""
342		}
343	
344		data, err := os.ReadFile(transcriptPath) //nolint:gosec // Path derived from agent hook input
345		if err != nil {
346			logging.Debug(ctx, "copilot-cli: failed to read transcript for model extraction",
347				"transcriptPath", transcriptPath, "err", err)
348			return ""
349		}
350	
351		events, err := parseEventsFromBytes(data)
352		if err != nil {
353			logging.Debug(ctx, "copilot-cli: failed to parse transcript for model extraction",
354				"transcriptPath", transcriptPath, "err", err)
355			return ""
356		}
357	
358		model := extractModelFromEvents(events)
359		if model == "" {
360			logging.Debug(ctx, "copilot-cli: no model found in transcript",
361				"transcriptPath", transcriptPath, "eventCount", len(events))
362		}
363	
364		return model
365	}
366	
367	// GetTranscriptPosition returns the current line count of a Copilot CLI transcript.
368	// Copilot CLI uses JSONL format, so position is the number of lines.
369	// This is a lightweight operation that only counts lines without parsing JSON.
370	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
371	// Returns 0 if the file doesn't exist or is empty.
372	func (c *CopilotCLIAgent) GetTranscriptPosition(path string) (int, error) {
373		if path == "" {
374			return 0, nil
375		}
376	
377		file, err := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
378		if err != nil {
379			if os.IsNotExist(err) {
380				return 0, nil
381			}
382			return 0, fmt.Errorf("failed to open transcript file: %w", err)
383		}
384		defer file.Close()
385	
386		reader := bufio.NewReader(file)
387		lineCount := 0
388	
389		for {
390			line, readErr := reader.ReadBytes('\n')
391			if readErr != nil {
392				if readErr == io.EOF {
393					if len(line) > 0 {
394						lineCount++ // Count final line without trailing newline
395					}
396					break
397				}
398				return 0, fmt.Errorf("failed to read transcript: %w", readErr)
399			}
400			lineCount++
401		}
402	
403		return lineCount, nil
404	}
405	
406	// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
407	// For Copilot CLI (JSONL format), offset is the starting line number.
408	// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
409	// Returns:
410	//   - files: list of file paths modified by Copilot (from tool.execution_complete events)
411	//   - currentPosition: total number of lines in the file
412	//   - error: any error encountered during reading
413	func (c *CopilotCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
414		if path == "" {
415			return nil, 0, nil
416		}
417	
418		file, openErr := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
419		if openErr != nil {
420			return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
421		}
422		defer file.Close()
423	
424		reader := bufio.NewReader(file)
425		var events []copilotEvent
426		lineNum := 0
427	
428		for {
429			lineData, readErr := reader.ReadBytes('\n')
430			if readErr != nil && readErr != io.EOF {
431				return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
432			}
433	
434			if len(lineData) > 0 {
435				lineNum++
436				if lineNum > startOffset {
437					var ev copilotEvent
438					if parseErr := json.Unmarshal(lineData, &ev); parseErr == nil {
439						events = append(events, ev)
440					}
441					// Skip malformed lines silently
442				}
443			}
444	
445			if readErr == io.EOF {
446				break
447			}
448		}
449	
450		return extractModifiedFilesFromEvents(events), lineNum, nil
451	}
452	
453	// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
454	func (c *CopilotCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
455		data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
456		if err != nil {
457			return nil, fmt.Errorf("failed to read transcript: %w", err)
458		}
459	
460		events, err := parseEventsFromOffset(data, fromOffset)
461		if err != nil {
462			return nil, fmt.Errorf("failed to parse transcript events: %w", err)
463		}
464		return extractPromptsFromEvents(events), nil
465	}
466	
467	// ExtractSummary extracts the last assistant message as a session summary.
468	func (c *CopilotCLIAgent) ExtractSummary(sessionRef string) (string, error) {
469		data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
470		if err != nil {
471			return "", fmt.Errorf("failed to read transcript: %w", err)
472		}
473	
474		events, err := parseEventsFromBytes(data)
475		if err != nil {
476			return "", fmt.Errorf("failed to parse transcript events: %w", err)
477		}
478		return extractSummaryFromEvents(events), nil
