package copilotcli

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// Compile-time interface checks.
var (
	_ agent.TranscriptAnalyzer = (*CopilotCLIAgent)(nil)
	_ agent.TokenCalculator    = (*CopilotCLIAgent)(nil)
)

// copilotEvent is a single line in events.jsonl.
type copilotEvent struct {
	Type      string          `json:"type"`
	Data      json.RawMessage `json:"data"`
	ID        string          `json:"id"`
	Timestamp string          `json:"timestamp"`
	ParentID  string          `json:"parentId"`
}

const (
	eventTypeUserMessage  = "user.message"
	eventTypeAssistantMsg = "assistant.message"
	eventTypeToolExecDone = "tool.execution_complete"
	eventTypeModelChange  = "session.model_change"
)

// userMessageData is the data payload for user.message events.
// IMPORTANT: The field is "content", not "message" — verified from real Copilot JSONL.
type userMessageData struct {
	Content string `json:"content"`
}

type assistantMessageData struct {
	Content string `json:"content"`
}

// modelChangeData is the data payload for session.model_change events.
// Copilot CLI emits this early in the transcript with the LLM model being used.
type modelChangeData struct {
	NewModel string `json:"newModel"`
}

type toolExecCompleteData struct {
	ToolCallID    string        `json:"toolCallId"`
	Model         string        `json:"model"`
	ToolTelemetry toolTelemetry `json:"toolTelemetry"`
}

type toolTelemetry struct {
	Metrics    toolMetrics    `json:"metrics"`
	Properties toolProperties `json:"properties"`
}

type toolMetrics struct {
	LinesAdded   int `json:"linesAdded"`
	LinesRemoved int `json:"linesRemoved"`
}

// toolProperties contains string-encoded metadata from tool execution.
// filePaths is a JSON-encoded string array, e.g. "[\"path/to/file.txt\"]".
type toolProperties struct {
	FilePaths string `json:"filePaths"`
}

// parseEventsFromBytes scans JSONL data and returns all parsed events.
// Malformed lines are silently skipped.
func parseEventsFromBytes(data []byte) ([]copilotEvent, error) {
	return parseEventsFromOffset(data, 0)
}

// parseEventsFromOffset scans JSONL data and returns events starting after
// the first startOffset lines. Malformed lines are silently skipped.
func parseEventsFromOffset(data []byte, startOffset int) ([]copilotEvent, error) {
	var events []copilotEvent
	scanner := bufio.NewScanner(bytes.NewReader(data))
	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 10*1024*1024) // 10 MB max line
	lineNum := 0

	for scanner.Scan() {
		lineNum++
		if lineNum <= startOffset {
			continue
		}

		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}

		var ev copilotEvent
		if err := json.Unmarshal(line, &ev); err != nil {
			continue // skip malformed lines
		}
		events = append(events, ev)
	}

	if err := scanner.Err(); err != nil {
		return events, fmt.Errorf("transcript scanner error: %w", err)
	}

	return events, nil
}

// extractModifiedFilesFromEvents collects file paths from tool.execution_complete
// events and returns a deduplicated list.
func extractModifiedFilesFromEvents(events []copilotEvent) []string {
	seen := make(map[string]bool)
	var files []string

	for i := range events {
		if events[i].Type != eventTypeToolExecDone {
			continue
		}

		var data toolExecCompleteData
		if err := json.Unmarshal(events[i].Data, &data); err != nil {
			continue
		}

		// filePaths is a JSON-encoded string array in properties, e.g. "[\"path/to/file\"]"
		if data.ToolTelemetry.Properties.FilePaths == "" {
			continue
		}
		var paths []string
		if err := json.Unmarshal([]byte(data.ToolTelemetry.Properties.FilePaths), &paths); err != nil {
			continue
		}
		for _, fp := range paths {
			if fp != "" && !seen[fp] {
				seen[fp] = true
				files = append(files, fp)
			}
		}
	}

	return files
}

// extractPromptsFromEvents collects content from user.message events.
func extractPromptsFromEvents(events []copilotEvent) []string {
	var prompts []string

	for i := range events {
		if events[i].Type != eventTypeUserMessage {
			continue
		}

		var data userMessageData
		if err := json.Unmarshal(events[i].Data, &data); err != nil {
			continue
		}

		if data.Content != "" {
			prompts = append(prompts, data.Content)
		}
	}

	return prompts
}

// extractSummaryFromEvents returns the content of the last assistant.message event.
func extractSummaryFromEvents(events []copilotEvent) string {
	for i := len(events) - 1; i >= 0; i-- {
		if events[i].Type != eventTypeAssistantMsg {
			continue
		}

		var data assistantMessageData
		if err := json.Unmarshal(events[i].Data, &data); err != nil {
			continue
		}

		if data.Content != "" {
			return data.Content
		}
	}

	return ""
}

// extractModelFromEvents returns the model from transcript events.
// First checks session.model_change events, then falls back to the model field
// in tool.execution_complete events (Copilot CLI includes model per tool call).
func extractModelFromEvents(events []copilotEvent) string {
	// Primary: session.model_change (explicit model declaration)
	for i := len(events) - 1; i >= 0; i-- {
		if events[i].Type != eventTypeModelChange {
			continue
		}

		var data modelChangeData
		if err := json.Unmarshal(events[i].Data, &data); err != nil {
			continue
		}

		if data.NewModel != "" {
			return data.NewModel
		}
	}

	// Fallback: tool.execution_complete events include a model field
	for i := len(events) - 1; i >= 0; i-- {
		if events[i].Type != eventTypeToolExecDone {
			continue
		}

		var data toolExecCompleteData
		if err := json.Unmarshal(events[i].Data, &data); err != nil {
			continue
		}

		if data.Model != "" {
			return data.Model
		}
	}

	return ""
}

// sessionShutdownData is the data payload for session.shutdown events.
// Contains aggregate model metrics for the entire session.
// modelMetrics is a JSON object keyed by model name (e.g. "claude-sonnet-4.6"),
// not an array — using map[string] here matches the real Copilot CLI wire format.
type sessionShutdownData struct {
	ModelMetrics map[string]modelMetric `json:"modelMetrics"`
}

// modelMetric contains per-model token usage aggregates.
// The model name is the map key in sessionShutdownData.ModelMetrics, not a field.
type modelMetric struct {
	Requests modelRequests `json:"requests"`
	Usage    modelUsage    `json:"usage"`
}

type modelRequests struct {
	Count int `json:"count"`
}

type modelUsage struct {
	InputTokens      int `json:"inputTokens"`
	OutputTokens     int `json:"outputTokens"`
	CacheReadTokens  int `json:"cacheReadTokens"`
	CacheWriteTokens int `json:"cacheWriteTokens"`
}

// assistantMessageTokenData is used as a fallback when session.shutdown is not
// yet available. Each assistant.message may carry an outputTokens field.
type assistantMessageTokenData struct {
	OutputTokens int `json:"outputTokens"`
}

const eventTypeSessionShutdown = "session.shutdown"

// CalculateTokenUsage computes token usage from the Copilot CLI JSONL transcript.
// For full transcripts (fromOffset == 0), it prefers session.shutdown, which
// contains session-wide aggregates. For sliced transcripts, session.shutdown
// would overcount because it is not checkpoint-scoped, so we fall back to
// summing assistant.message outputTokens within the slice.
func (c *CopilotCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
	events, err := parseEventsFromOffset(transcriptData, fromOffset)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
	}

	return extractTokenUsageFromEvents(events, fromOffset == 0), nil
}

// extractTokenUsageFromEvents extracts token usage from parsed events.
// Prefers session.shutdown aggregate only when the caller is looking at the
// full transcript; otherwise falls back to per-message outputTokens.
func extractTokenUsageFromEvents(events []copilotEvent, preferSessionShutdown bool) *agent.TokenUsage {
	if preferSessionShutdown {
		// session.shutdown is authoritative, but only for full-session totals.
		for i := len(events) - 1; i >= 0; i-- {
			if events[i].Type != eventTypeSessionShutdown {
				continue
			}

			var data sessionShutdownData
			if err := json.Unmarshal(events[i].Data, &data); err != nil {
				logging.Debug(context.Background(), "copilot-cli: session.shutdown data unmarshal failed",
					"err", err)
				continue
			}

			if len(data.ModelMetrics) == 0 {
				continue
			}

			// Sum across all models.
			usage := &agent.TokenUsage{}
			for _, m := range data.ModelMetrics {
				usage.InputTokens += m.Usage.InputTokens
				usage.OutputTokens += m.Usage.OutputTokens
				usage.CacheReadTokens += m.Usage.CacheReadTokens
				usage.CacheCreationTokens += m.Usage.CacheWriteTokens
				usage.APICallCount += m.Requests.Count
			}
			return usage
		}
	}

	// Fallback: sum outputTokens from assistant.message events
	usage := &agent.TokenUsage{}
	for i := range events {
		if events[i].Type != eventTypeAssistantMsg {
			continue
		}

		var data assistantMessageTokenData
		if err := json.Unmarshal(events[i].Data, &data); err != nil {
			continue
		}
		usage.OutputTokens += data.OutputTokens
		if data.OutputTokens > 0 {
			usage.APICallCount++
		}
	}

	return usage
}

// ExtractModelFromTranscript extracts the LLM model name from a Copilot CLI
// transcript. It prefers session.model_change events (explicit model
// declarations), but falls back to the model field on tool.execution_complete
// events for Copilot CLI versions that do not emit session.model_change.
// Returns the last observed model, or empty string if unavailable.
func ExtractModelFromTranscript(ctx context.Context, transcriptPath string) string {
	if transcriptPath == "" {
		return ""
	}

	data, err := os.ReadFile(transcriptPath) //nolint:gosec // Path derived from agent hook input
	if err != nil {
		logging.Debug(ctx, "copilot-cli: failed to read transcript for model extraction",
			"transcriptPath", transcriptPath, "err", err)
		return ""
	}

	events, err := parseEventsFromBytes(data)
	if err != nil {
		logging.Debug(ctx, "copilot-cli: failed to parse transcript for model extraction",
			"transcriptPath", transcriptPath, "err", err)
		return ""
	}

	model := extractModelFromEvents(events)
	if model == "" {
		logging.Debug(ctx, "copilot-cli: no model found in transcript",
			"transcriptPath", transcriptPath, "eventCount", len(events))
	}

	return model
}

// GetTranscriptPosition returns the current line count of a Copilot CLI transcript.
// Copilot CLI uses JSONL format, so position is the number of lines.
// This is a lightweight operation that only counts lines without parsing JSON.
// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
// Returns 0 if the file doesn't exist or is empty.
func (c *CopilotCLIAgent) GetTranscriptPosition(path string) (int, error) {
	if path == "" {
		return 0, nil
	}

	file, err := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("failed to open transcript file: %w", err)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	lineCount := 0

	for {
		line, readErr := reader.ReadBytes('\n')
		if readErr != nil {
			if readErr == io.EOF {
				if len(line) > 0 {
					lineCount++ // Count final line without trailing newline
				}
				break
			}
			return 0, fmt.Errorf("failed to read transcript: %w", readErr)
		}
		lineCount++
	}

	return lineCount, nil
}

// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
// For Copilot CLI (JSONL format), offset is the starting line number.
// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
// Returns:
//   - files: list of file paths modified by Copilot (from tool.execution_complete events)
//   - currentPosition: total number of lines in the file
//   - error: any error encountered during reading
func (c *CopilotCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
	if path == "" {
		return nil, 0, nil
	}

	file, openErr := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
	if openErr != nil {
		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	var events []copilotEvent
	lineNum := 0

	for {
		lineData, readErr := reader.ReadBytes('\n')
		if readErr != nil && readErr != io.EOF {
			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
		}

		if len(lineData) > 0 {
			lineNum++
			if lineNum > startOffset {
				var ev copilotEvent
				if parseErr := json.Unmarshal(lineData, &ev); parseErr == nil {
					events = append(events, ev)
				}
				// Skip malformed lines silently
			}
		}

		if readErr == io.EOF {
			break
		}
	}

	return extractModifiedFilesFromEvents(events), lineNum, nil
}

// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
func (c *CopilotCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	events, err := parseEventsFromOffset(data, fromOffset)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript events: %w", err)
	}
	return extractPromptsFromEvents(events), nil
}

// ExtractSummary extracts the last assistant message as a session summary.
func (c *CopilotCLIAgent) ExtractSummary(sessionRef string) (string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return "", fmt.Errorf("failed to read transcript: %w", err)
	}

	events, err := parseEventsFromBytes(data)
	if err != nil {
		return "", fmt.Errorf("failed to parse transcript events: %w", err)
	}
	return extractSummaryFromEvents(events), nil
}

package copilotcli

// CopilotHooksFile represents the .github/hooks/entire.json structure.
// Copilot CLI uses a flat JSON file with version and hooks sections.
// All JSON files in .github/hooks/ are auto-discovered by the Copilot CLI.
//

type CopilotHooksFile struct {
	Version int          `json:"version"`
	Hooks   CopilotHooks `json:"hooks"`
}

// CopilotHooks contains all hook configurations using camelCase keys.
//

type CopilotHooks struct {
	UserPromptSubmitted []CopilotHookEntry `json:"userPromptSubmitted,omitempty"`
	SessionStart        []CopilotHookEntry `json:"sessionStart,omitempty"`
	AgentStop           []CopilotHookEntry `json:"agentStop,omitempty"`
	SessionEnd          []CopilotHookEntry `json:"sessionEnd,omitempty"`
	SubagentStop        []CopilotHookEntry `json:"subagentStop,omitempty"`
	PreToolUse          []CopilotHookEntry `json:"preToolUse,omitempty"`
	PostToolUse         []CopilotHookEntry `json:"postToolUse,omitempty"`
	ErrorOccurred       []CopilotHookEntry `json:"errorOccurred,omitempty"`
}

// CopilotHookEntry represents a single hook command.
// Copilot CLI hooks have a type field ("command") and a bash field for the command string.
// Optional fields (cwd, timeoutSec, env, comment) are preserved on round-trip.

type CopilotHookEntry struct {
	Type       string            `json:"type"`
	Bash       string            `json:"bash"`
	Comment    string            `json:"comment,omitempty"`
	Cwd        string            `json:"cwd,omitempty"`
	TimeoutSec int               `json:"timeoutSec,omitempty"`
	Env        map[string]string `json:"env,omitempty"`
}

package copilotcli

import (
	"context"
	"fmt"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// Ensure CopilotCLIAgent implements HookSupport at compile time.
var _ agent.HookSupport = (*CopilotCLIAgent)(nil)

// Copilot CLI hook names - these become subcommands under `entire hooks copilot-cli`
const (
	HookNameUserPromptSubmitted = "user-prompt-submitted"
	HookNameSessionStart        = "session-start"
	HookNameAgentStop           = "agent-stop"
	HookNameSessionEnd          = "session-end"
	HookNameSubagentStop        = "subagent-stop"
	HookNamePreToolUse          = "pre-tool-use"
	HookNamePostToolUse         = "post-tool-use"
	HookNameErrorOccurred       = "error-occurred"
)

// HookNames returns all hook verbs Copilot CLI supports.
// These become subcommands: entire hooks copilot-cli <verb>
func (c *CopilotCLIAgent) HookNames() []string {
	return []string{
		HookNameUserPromptSubmitted,
		HookNameSessionStart,
		HookNameAgentStop,
		HookNameSessionEnd,
		HookNameSubagentStop,
		HookNamePreToolUse,
		HookNamePostToolUse,
		HookNameErrorOccurred,
	}
}

// ParseHookEvent translates a Copilot CLI hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance (pass-through hooks).
//
// For VS Code payloads (detected via hookEventName), the event name is validated
// against the CLI subcommand. Mismatches are silently skipped to avoid processing
// a payload that doesn't match the hook being invoked.
func (c *CopilotCLIAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	// Pass-through hooks: skip immediately without reading stdin.
	switch hookName {
	case HookNamePreToolUse, HookNamePostToolUse, HookNameErrorOccurred:
		return nil, nil //nolint:nilnil // Pass-through hooks have no lifecycle action
	}

	// For lifecycle hooks, read and parse the envelope first so we can
	// validate VS Code hookEventName before constructing an event.
	env, err := c.readHookEnvelope(stdin)
	if err != nil {
		return nil, err
	}

	// VS Code payloads: validate hookEventName matches the CLI subcommand.
	if env.Host == HostVSCode && env.HookEventName != "" {
		if !validateVSCodeEvent(env, hookName) {
			logging.Debug(ctx, "copilot-cli: skipping VS Code event with mismatched hookEventName",
				"hookEventName", env.HookEventName, "hookName", hookName)
			return nil, nil //nolint:nilnil // Mismatched VS Code event — skip silently.
		}
	}

	switch hookName {
	case HookNameUserPromptSubmitted:
		return c.buildUserPromptSubmitted(ctx, env), nil
	case HookNameSessionStart:
		return c.buildSessionStart(env), nil
	case HookNameAgentStop:
		return c.buildAgentStop(ctx, env), nil
	case HookNameSessionEnd:
		return c.buildSessionEnd(env), nil
	case HookNameSubagentStop:
		return c.buildSubagentStop(env), nil
	default:
		logging.Debug(ctx, "copilot-cli: ignoring unknown hook", "hook", hookName)
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

// --- Internal event builders (envelope already parsed) ---

func (c *CopilotCLIAgent) buildUserPromptSubmitted(ctx context.Context, env *hookEnvelope) *agent.Event {
	transcriptRef := env.TranscriptPath
	if transcriptRef == "" {
		transcriptRef = c.resolveTranscriptRef(ctx, env.SessionID)
	}

	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  env.SessionID,
		SessionRef: transcriptRef,
		Prompt:     env.Prompt,
		Timestamp:  env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildSessionStart(env *hookEnvelope) *agent.Event {
	return &agent.Event{
		Type:      agent.SessionStart,
		SessionID: env.SessionID,
		Timestamp: env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildAgentStop(ctx context.Context, env *hookEnvelope) *agent.Event {
	var model string
	if env.TranscriptPath != "" {
		model = ExtractModelFromTranscript(ctx, env.TranscriptPath)
	}

	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  env.SessionID,
		SessionRef: env.TranscriptPath,
		Model:      model,
		Timestamp:  env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildSessionEnd(env *hookEnvelope) *agent.Event {
	return &agent.Event{
		Type:      agent.SessionEnd,
		SessionID: env.SessionID,
		Timestamp: env.Timestamp,
	}
}

func (c *CopilotCLIAgent) buildSubagentStop(env *hookEnvelope) *agent.Event {
	return &agent.Event{
		Type:      agent.SubagentEnd,
		SessionID: env.SessionID,
		Timestamp: env.Timestamp,
	}
}

func (c *CopilotCLIAgent) readHookEnvelope(stdin io.Reader) (*hookEnvelope, error) {
	data, err := io.ReadAll(stdin)
	if err != nil {
		return nil, fmt.Errorf("failed to read hook input: %w", err)
	}
	return parseHookEnvelope(data)
}

// resolveTranscriptRef computes the transcript path from the session ID.
// Copilot CLI stores transcripts at ~/.copilot/session-state/<sessionId>/events.jsonl.
// The userPromptSubmitted hook does not include a transcriptPath field, so we compute it.
func (c *CopilotCLIAgent) resolveTranscriptRef(ctx context.Context, sessionID string) string {
	// GetSessionDir ignores the repoPath parameter for Copilot CLI since session
	// state is always in ~/.copilot/session-state/ (not repo-specific).
	sessionDir, err := c.GetSessionDir("")
	if err != nil {
		logging.Warn(ctx, "copilot-cli: failed to resolve transcript path", "sessionID", sessionID, "err", err)
		return ""
	}
	return c.ResolveSessionFile(sessionDir, sessionID)
}

package strategy

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// transcriptFileExists reports whether the transcript file at the given path
// actually exists on disk. Returns false for empty paths. This is used by
// PrepareCommitMsg to avoid adding checkpoint trailers when the transcript
// file is not locally available (e.g., cloud agents that set TranscriptPath
// in hook payloads but don't write the file to the runner's filesystem).
func transcriptFileExists(path string) bool {
	if path == "" {
		return false
	}
	_, err := os.Stat(path)
	return err == nil
}

// resolveTranscriptPath returns the current path to the session's transcript file.
// If the file exists at state.TranscriptPath, that path is returned immediately.
//
// If the file is missing (os.ErrNotExist), the function re-resolves the path
// using the agent's ResolveSessionFile method. This handles agents that relocate
// transcripts mid-session (e.g., Cursor CLI switching from a flat layout
// <dir>/<id>.jsonl to a nested layout <dir>/<id>/<id>.jsonl).
//
// On successful re-resolution, state.TranscriptPath is updated so that
// subsequent reads use the correct path without repeating the resolution.
func resolveTranscriptPath(state *SessionState) (string, error) {
	if state.TranscriptPath == "" {
		return "", errors.New("no transcript path in session state")
	}

	// Fast path: file exists at the stored location.
	if _, err := os.Stat(state.TranscriptPath); err == nil {
		return state.TranscriptPath, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		// Non-ENOENT error (permission denied, etc.) — return as-is.
		return "", fmt.Errorf("failed to access transcript: %w", err)
	}

	// File not found — attempt re-resolution via the agent.
	ag, agErr := agent.GetByAgentType(state.AgentType)
	if agErr != nil {
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Extract the session dir and agent session ID from the stored path.
	// Stored path format: <sessionDir>/<agentSessionID>.jsonl
	sessionDir := filepath.Dir(state.TranscriptPath)
	base := filepath.Base(state.TranscriptPath)
	agentSessionID := strings.TrimSuffix(base, filepath.Ext(base))

	resolved := ag.ResolveSessionFile(sessionDir, agentSessionID)
	if resolved == state.TranscriptPath {
		// Agent resolved to the same path — file genuinely doesn't exist.
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Check if the re-resolved path exists.
	if _, err := os.Stat(resolved); err != nil {
		return "", fmt.Errorf("transcript not found at %s (also tried %s): %w", state.TranscriptPath, resolved, os.ErrNotExist)
	}

	// Update state so subsequent reads use the correct path.
	state.TranscriptPath = resolved
	return resolved, nil
}

