2	
3	import (
4		"context"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	
10		"github.com/entireio/cli/cmd/entire/cli/agent"
11		"github.com/stretchr/testify/require"
12	)
13	
14	// testSessionID is the UUID used in captured Copilot CLI hook payloads.
15	const testSessionID = "b0ff98c0-8e01-4b73-bf92-9649b139931b"
16	
17	func TestParseHookEvent_UserPromptSubmitted(t *testing.T) {
18		t.Parallel()
19	
20		ag := &CopilotCLIAgent{}
21		input := `{"timestamp":1771480081360,"cwd":"/path/to/repo","sessionId":"` + testSessionID + `","prompt":"hi"}`
22	
23		event, err := ag.ParseHookEvent(context.Background(), HookNameUserPromptSubmitted, strings.NewReader(input))
24	
25		if err != nil {
26			t.Fatalf("unexpected error: %v", err)
27		}
28		require.NotNil(t, event, "expected event, got nil")
29		if event.Type != agent.TurnStart {
30			t.Errorf("expected event type %v, got %v", agent.TurnStart, event.Type)
31		}
32		if event.SessionID != testSessionID {
33			t.Errorf("expected session_id %q, got %q", testSessionID, event.SessionID)
34		}
35		if event.Prompt != "hi" {
36			t.Errorf("expected prompt 'hi', got %q", event.Prompt)
37		}
38		if event.Timestamp.IsZero() {
39			t.Error("expected non-zero timestamp")
40		}
